def count_cycles(m):
    if m <= 1:
        return 0

    elements = list(range(1, m))
    visited = [False] * m
    cycle_count = 0

    for start_element in elements:
        if not visited[start_element]:
            cycle_count += 1
            current = start_element

            while not visited[current]:
                visited[current] = True

                next_element = (3 * current) % m

                # Since 3 is coprime to m, next_element is guaranteed to be in {1, ..., m-1}
                current = next_element

    return cycle_count

# Search for the second largest m < 200 such that 3 does not divide m and cycle count is odd.
m_candidates = []
for m in range(199, 0, -1):
    if m % 3 != 0:
        num_cycles = count_cycles(m)
        if num_cycles % 2 != 0:
            m_candidates.append(m)

if len(m_candidates) >= 2:
    # m_candidates is already sorted descendingly because we iterated backwards
    second_largest_m = m_candidates[1]
    print(f"The second largest m is: {second_largest_m}")
else:
    print("Fewer than two candidates found.")
